pub fn extractDynamicSpecifierShape(p: *P, arg: Expr, buf: *std.array_list.Managed(u8)) ![]const u8 {
            if (arg.data.@"as"(.e_template)) |tmpl| {
                _ = &tmpl;
                if ((tmpl.tag != null)) {
                    return "";
                }
                switch (tmpl.head) {
.cooked => |*head| {
_ = try buf.appendSlice(head.slice(p.allocator));
},
.raw => {
return "";
},
}
                for (cp_mut_slice(&tmpl.parts)) |*part| {
                    _ = &part;
                    _ = try buf.append(0);
                    switch ((part.*).tail) {
.cooked => |*tail| {
_ = try buf.appendSlice(tail.slice(p.allocator));
},
.raw => {
return "";
},
}
                }
                return buf.items;
            }
            return "";
    }

pub fn checkDynamicSpecifier(p: *P, arg: Expr, loc: logger.Loc, comptime kind: []const u8) !void {
            if (((!p.options.bundle) or (p.options.allow_unresolved.* == .all))) {
                return;
            }
            var shape_buf = std.array_list.Managed(u8).init(p.allocator);
            _ = &shape_buf;
            var _shape_guard = DeinitGuard(std.array_list.Managed(u8)){ .ptr = (&shape_buf) };
