            const symbol: *const Symbol = (&p.symbols.items[@as(usize, @intCast(ident.ref.innerIndex()))]);
            return (symbol.use_count_estimate > 0);
},
.b_array => |array| {
for (array.items) |item| {
                _ = &item;
                if (isBindingUsed(p, item.binding, default_export_ref)) {
