pub fn handleIdentifier(p: *P, loc: logger.Loc, ident: E.Identifier, original_name: ?[]const u8, opts: IdentifierOpts) Expr {
            const sym_ref = ident.ref;
            if (p.options.features.inlining) {
                if (p.const_values.get(sym_ref)) |replacement| {
                    _ = &replacement;
                    _ = p.ignoreUsage(sym_ref);
                    return replacement;
                }
            }
            if (((p.options.bundle and ((opts.assign_target != .none) or opts.is_delete_target)) and (p.symbols.items[@as(usize, @intCast(sym_ref.innerIndex()))].kind == .@"import"))) {
                const r = js_lexer.rangeOfIdentifier(p.source, loc);
                _ = ((p.log.addRangeErrorFmt(p.source, r, p.allocator, "Cannot assign to import \"{s}\"", .{ p.symbols.items[@as(usize, @intCast(sym_ref.innerIndex()))].original_name })) catch unreachable);
            }
            if (((opts.assign_target == .none) and (!opts.is_delete_target))) {
                const symbol = (&p.symbols.items[@as(usize, @intCast(sym_ref.inner_index))]);
                if (symbol.namespace_alias) |ns_alias| {
                    _ = &ns_alias;
                    if (p.ref_to_ts_namespace_member.get(ns_alias.namespace_ref)) |ts_member_data| {
                        _ = &ts_member_data;
                        if ((ts_member_data == .namespace)) {
                            if (ts_member_data.namespace.get(ns_alias.alias)) |member| {
                                _ = &member;
                                switch (member.data) {
.enum_number => |num| {
return p.wrapInlinedEnum(.{ .loc = loc, .data = .{ .e_number = .{ .value = num } } }, p.symbols.items[@as(usize, @intCast(sym_ref.inner_index))].original_name);
},
.enum_string => |str| {
return p.wrapInlinedEnum(.{ .loc = loc, .data = .{ .e_string = str } }, p.symbols.items[@as(usize, @intCast(sym_ref.inner_index))].original_name);
},
.namespace => |map| {
const expr = p.newExpr(E.Dot{ .target = p.newExpr(E.Identifier.init(ns_alias.namespace_ref), loc), .name = ns_alias.alias, .name_loc = loc }, loc);
                                p.ts_namespace = .{ .expr = expr.data, .map = map };
                                return expr;
},
else => {

},
}
                            }
                        }
                    }
                    return p.newExpr(E.ImportIdentifier{ .ref = ident.ref, .was_originally_identifier = true }, loc);
                }
            }
            if (p.is_import_item.contains(sym_ref)) {
                return p.newExpr(E.ImportIdentifier{ .ref = sym_ref, .was_originally_identifier = opts.was_originally_identifier }, loc);
            }
            if (is_typescript_enabled) {
                if (p.ref_to_ts_namespace_member.get(sym_ref)) |member_data| {
                    _ = &member_data;
                    switch (member_data) {
.enum_number => |num| {
return p.wrapInlinedEnum(.{ .loc = loc, .data = .{ .e_number = .{ .value = num } } }, p.symbols.items[@as(usize, @intCast(sym_ref.inner_index))].original_name);
},
.enum_string => |str| {
return p.wrapInlinedEnum(.{ .loc = loc, .data = .{ .e_string = str } }, p.symbols.items[@as(usize, @intCast(sym_ref.inner_index))].original_name);
},
.namespace => |map| {
const expr: Expr = .{ .data = .{ .e_identifier = ident }, .loc = loc };
                    p.ts_namespace = .{ .expr = expr.data, .map = map };
                    return expr;
},
else => {

},
}
                }
                if (p.is_exported_inside_namespace.get(sym_ref)) |ns_ref| {
                    _ = &ns_ref;
                    const name = p.symbols.items[@as(usize, @intCast(sym_ref.innerIndex()))].original_name;
                    _ = p.recordUsage(ns_ref);
                    const prop = p.newExpr(E.Dot{ .target = p.newExpr(E.Identifier.init(ns_ref), loc), .name = name, .name_loc = loc }, loc);
                    if (((p.ts_namespace.expr == .e_identifier) and p.ts_namespace.expr.e_identifier.ref.eql(ident.ref))) {
                        p.ts_namespace.expr = prop.data;
                    }
                    return prop;
                }
            }
            if (original_name) |name| {
                _ = &name;
                const result = ((p.findSymbol(loc, name)) catch unreachable);
                var id_clone = ident;
                _ = &id_clone;
                id_clone.ref = result.ref;
                return p.newExpr(id_clone, loc);
            }
            return .{ .data = .{ .e_identifier = ident }, .loc = loc };
    }

pub fn generateImportStmtForBakeResponse(p: *P, parts: *ListManaged(js_ast.Part)) !void {
