pub fn generateImportStmt(p: *P, import_path: []const u8, imports: anytype, parts: *ListManaged(js_ast.Part), symbols: anytype, additional_stmt: ?Stmt, comptime prefix: []const u8, comptime is_internal: bool) !void {
            const allocator = p.allocator;
            const import_record_i = p.addImportRecordByRange(.stmt, logger.Range.None, import_path);
            var import_record: *ImportRecord = (&p.import_records.items[@as(usize, @intCast(import_record_i))]);
            _ = &import_record;
            if (comptime is_internal) {
                import_record.path.namespace = "runtime";
            }
            import_record.flags.is_internal = is_internal;
            const import_path_identifier = try (if (@typeInfo(@TypeOf(import_record.path)) == .@"enum" or @typeInfo(@TypeOf(import_record.path)) == .@"union") @tagName(import_record.path) else import_record.path.name).nonUniqueNameString(allocator);
            var namespace_identifier = try allocator.alloc(u8, (import_path_identifier.len + prefix.len));
            _ = &namespace_identifier;
            const clause_items = try allocator.alloc(js_ast.ClauseItem, imports.len);
            var stmts = try allocator.alloc(Stmt, (1 + (if ((additional_stmt != null)) (if (comptime @typeInfo(@TypeOf(1)) == .@"enum") cp_cast_int(usize, @intFromEnum(1)) else cp_cast_int(usize, 1)) else (if (comptime @typeInfo(@TypeOf(0)) == .@"enum") cp_cast_int(usize, @intFromEnum(0)) else cp_cast_int(usize, 0)))));
            _ = &stmts;
            var declared_symbols: DeclaredSymbol.List = .{};
            _ = &declared_symbols;
            _ = try declared_symbols.ensureTotalCapacity(allocator, (imports.len + 1));
            _ = bun.copy(u8, namespace_identifier, prefix);
            _ = bun.copy(u8, namespace_identifier[prefix.len..], import_path_identifier);
            const namespace_ref = try p.newSymbol(.other, namespace_identifier);
            _ = declared_symbols.appendAssumeCapacity(.{ .ref = namespace_ref, .is_top_level = true });
            _ = try p.module_scope.generated.append(allocator, namespace_ref);
            var imp_i: usize = 0;
            _ = &imp_i;
            while ((imp_i < imports.len)) : (imp_i = (imp_i + 1)) {
                const alias = imports[@as(usize, @intCast(imp_i))];
                var clause_item = (&clause_items[@as(usize, @intCast(imp_i))]);
                _ = &clause_item;
                const sym_ref = ((symbols.get(alias)) orelse (unreachable));
                const alias_name = (if ((@TypeOf(symbols) == RuntimeImports)) RuntimeImports.all[@as(usize, @intCast(alias))] else alias);
                clause_item.* = js_ast.ClauseItem{ .alias = alias_name, .original_name = alias_name, .alias_loc = logger.Loc{  }, .name = LocRef{ .ref = sym_ref, .loc = logger.Loc{  } } };
                _ = declared_symbols.appendAssumeCapacity(.{ .ref = sym_ref, .is_top_level = true });
                if (p.options.features.hot_module_reloading) {
                    const symbol = (&p.symbols.items[@as(usize, @intCast(sym_ref.inner_index))]);
                    if ((symbol.namespace_alias == null)) {
                        symbol.namespace_alias = .{ .namespace_ref = namespace_ref, .alias = alias_name, .import_record_index = import_record_i };
                    }
                }
                _ = try p.is_import_item.put(allocator, sym_ref, undefined);
                _ = try p.named_imports.put(allocator, sym_ref, js_ast.NamedImport{ .alias = alias_name, .alias_loc = logger.Loc{  }, .namespace_ref = namespace_ref, .import_record_index = import_record_i });
            }
            stmts[cp_cast_int(usize, 0)] = p.s(S.Import{ .namespace_ref = namespace_ref, .items = clause_items, .import_record_index = import_record_i, .is_single_line = true }, logger.Loc{  });
            if (additional_stmt) |add| {
                _ = &add;
                stmts[cp_cast_int(usize, 1)] = add;
            }
            var import_records = try allocator.alloc(@TypeOf(import_record_i), 1);
            _ = &import_records;
            import_records[cp_cast_int(usize, 0)] = import_record_i;
            _ = ((parts.append(js_ast.Part{ .stmts = stmts, .declared_symbols = declared_symbols, .import_record_indices = bun.BabyList(u32).fromOwnedSlice(import_records), .tag = .runtime })) catch unreachable);
    }

