pub fn generateReactRefreshImportHmr(p: *P, parts: *ListManaged(js_ast.Part), import_path: []const u8, clauses: []const ReactRefreshImportClause, comptime hot_module_reloading: bool) !void {
            const allocator = p.allocator;
            const import_record_index = p.addImportRecordByRange(.stmt, logger.Range.None, import_path);
            const Item = (if (hot_module_reloading) B.Object.Property else js_ast.ClauseItem);
            const len = ((1 + (if (comptime @typeInfo(@TypeOf(@intFromBool(p.react_refresh.register_used))) == .@"enum") cp_cast_int(usize, @intFromEnum(@intFromBool(p.react_refresh.register_used))) else cp_cast_int(usize, @intFromBool(p.react_refresh.register_used)))) + (if (comptime @typeInfo(@TypeOf(@intFromBool(p.react_refresh.signature_used))) == .@"enum") cp_cast_int(usize, @intFromEnum(@intFromBool(p.react_refresh.signature_used))) else cp_cast_int(usize, @intFromBool(p.react_refresh.signature_used))));
            var items = try List(Item).initCapacity(allocator, len);
            _ = &items;
            const stmts = try allocator.alloc(Stmt, 1);
            var declared_symbols: DeclaredSymbol.List = .{};
            _ = &declared_symbols;
            _ = try declared_symbols.ensureTotalCapacity(allocator, len);
            const namespace_ref = try p.newSymbol(.other, "RefreshRuntime");
            _ = declared_symbols.appendAssumeCapacity(.{ .ref = namespace_ref, .is_top_level = true });
            _ = try p.module_scope.generated.append(allocator, namespace_ref);
            for (cp_iter_slice(clauses)) |entry| {
                _ = &entry;
                if (entry.enabled) {
                    if (hot_module_reloading) {
                        _ = items.appendAssumeCapacity(B.Property{ .key = p.newExpr(E.String{ .data = entry.name }, logger.Loc.Empty), .value = p.b(B.Identifier{ .ref = entry.ref }, logger.Loc.Empty) });
                    } else {
                        _ = items.appendAssumeCapacity(js_ast.ClauseItem{ .alias = entry.name, .original_name = entry.name, .alias_loc = logger.Loc{  }, .name = LocRef{ .ref = entry.ref, .loc = logger.Loc{  } } });
                    }
                    _ = declared_symbols.appendAssumeCapacity(.{ .ref = entry.ref, .is_top_level = true });
                    _ = try p.is_import_item.put(allocator, entry.ref, undefined);
                    _ = try p.named_imports.put(allocator, entry.ref, .{ .alias = entry.name, .alias_loc = logger.Loc.Empty, .namespace_ref = namespace_ref, .import_record_index = import_record_index });
                }
            }
            stmts[cp_cast_int(usize, 0)] = p.s((if (hot_module_reloading) S.Local{ .kind = .k_const, .decls = try Decl.List.fromSlice(p.allocator, (&.{ .{ .binding = p.b(B.Object{ .properties = items.items }, logger.Loc.Empty), .value = p.newExpr(E.RequireString{ .import_record_index = import_record_index }, logger.Loc.Empty) } })) } else S.Import{ .namespace_ref = namespace_ref, .items = items.items, .import_record_index = import_record_index, .is_single_line = false }), logger.Loc.Empty);
            _ = try parts.append(.{ .stmts = stmts, .declared_symbols = declared_symbols, .import_record_indices = try bun.BabyList(u32).fromSlice(allocator, (&.{ import_record_index })), .tag = .runtime });
    }

pub fn substituteSingleUseSymbolInStmt(p: *P, stmt: Stmt, sym_ref: Ref, replacement: Expr) bool {
            const expr: *Expr = brk: {
            switch (stmt.data) {
.s_expr => |exp| {
break :brk (&(if (@typeInfo(@TypeOf(exp)) == .@"enum") @intFromEnum(exp) else exp.value));
},
.s_throw => |throw| {
