            }
},
else => {

},
}
            return false;
};
            const replacement_can_be_removed = p.exprCanBeRemovedIfUnused((&replacement));
            switch (p.substituteSingleUseSymbolInExpr(expr.*, sym_ref, replacement, replacement_can_be_removed)) {
.success => |result| {
