                _ = items.appendAssumeCapacity(js_ast.ArrayBinding{ .binding = ((res.binding) orelse (p.b(std.mem.zeroes(B.Missing), item.loc))), .default_value = res.expr });
                i = (i + 1);
            }
            return p.b(B.Array{ .items = items.items, .has_spread = is_spread, .is_single_line = ex.is_single_line }, expr.loc);
},
.e_object => |ex| {
if (ex.comma_after_spread) |sp| {
                _ = &sp;
                _ = ((invalid_loc.append(.{ .loc = sp, .kind = .spread })) catch unreachable);
            }
            if (ex.is_parenthesized) {
                _ = ((invalid_loc.append(.{ .loc = p.source.rangeOfOperatorBefore(expr.loc, "(").loc, .kind = .parentheses })) catch unreachable);
            }
            var properties = ((List(B.Property).initCapacity(p.allocator, ex.properties.len)) catch unreachable);
            _ = &properties;
