                    _ = ((invalid_loc.append(.{ .loc = (item.*).key.?.loc, .kind = (if ((item.*).flags.contains(.is_method)) InvalidLoc.Tag.method else (if (((item.*).kind == .get)) InvalidLoc.Tag.getter else InvalidLoc.Tag.setter)) })) catch unreachable);
