                        _ = &remapped_path;
                        const new_import_id = p.addImportRecord(.stmt, path.loc, remapped_path);
                        _ = try p.@"macro".refs.put(sym_ref, .{ .import_record_id = new_import_id, .name = item.alias });
                        p.import_records.items[@as(usize, @intCast(new_import_id))].path.namespace = js_ast.Macro.namespace;
                        p.import_records.items[@as(usize, @intCast(new_import_id))].flags.is_unused = true;
                        if (comptime only_scan_imports_and_do_not_visit) {
                            p.import_records.items[@as(usize, @intCast(new_import_id))].flags.is_internal = true;
                            p.import_records.items[@as(usize, @intCast(new_import_id))].path.is_disabled = true;
