pub fn validateAndSetImportType(p: *P, path: *const ParsedPath, stmt: *S.Import) !void {
            @branchHint(.cold);
            if (path.loader) |loader| {
                _ = &loader;
                p.import_records.items[@as(usize, @intCast(stmt.import_record_index))].loader = loader;
                if (((loader == .sqlite) or (loader == .sqlite_embedded))) {
                    for (stmt.items) |*item| {
                        _ = &item;
                        if ((!(strings.eqlComptime((item.*).alias, "default") or strings.eqlComptime((item.*).alias, "db")))) {
                            _ = try p.log.addError(p.source, (if (@typeInfo(@TypeOf((item.*))) == .@"enum" or @typeInfo(@TypeOf((item.*))) == .@"union") @tagName((item.*)) else (item.*).name).loc, "sqlite imports only support the \"default\" or \"db\" imports");
                            break;
                        }
                    }
                } else {
                    if (((loader == .file) or (loader == .text))) {
                        for (stmt.items) |*item| {
                            _ = &item;
                            if ((!strings.eqlComptime((item.*).alias, "default"))) {
                                _ = try p.log.addError(p.source, (if (@typeInfo(@TypeOf((item.*))) == .@"enum" or @typeInfo(@TypeOf((item.*))) == .@"union") @tagName((item.*)) else (item.*).name).loc, "This loader type only supports the \"default\" import");
