.e_function => |func_container| {
if ((if (@typeInfo(@TypeOf(func_container.func)) == .@"enum" or @typeInfo(@TypeOf(func_container.func)) == .@"union") @tagName(func_container.func) else func_container.func.name)) |_name| {
                _ = &_name;
