}
            return ((createDefaultName(p, loc)) catch unreachable);
    }

pub fn discardScopesUpTo(p: *P, scope_index: usize) void {
            const scope = p.current_scope;
            var children = scope.children;
            _ = &children;
            defer {
            scope.children = children;
            }
            for (cp_iter_slice(p.scopes_in_order.items[scope_index..])) |_child| {
                _ = &_child;
                if ((_child == null)) {
                    continue;
                }
                const child = _child.?;
                if ((child.scope.parent == p.current_scope)) {
                    var i: usize = (children.len - 1);
                    _ = &i;
                    while ((i >= 0)) {
                        if (((children.mut(i)).* == child.scope)) {
                            _ = children.orderedRemove(i);
                            break;
                        }
                        i = (i - 1);
                    }
                }
            }
            _ = p.scopes_in_order.shrinkRetainingCapacity(scope_index);
    }

pub fn defineExportedNamespaceBinding(p: *P, exported_members: *js_ast.TSNamespaceMemberMap, binding: Binding) !void {
            switch (binding.data) {
